CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS weigh_ins (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,weight REAL NOT NULL,recorded_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workout_logs (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,week INTEGER NOT NULL,day INTEGER NOT NULL,started_at TEXT DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS exercise_logs (id TEXT PRIMARY KEY,workout_id TEXT NOT NULL,user_id TEXT NOT NULL,exercise TEXT NOT NULL,set_number INTEGER NOT NULL,reps INTEGER,weight REAL,done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY,goal_weight REAL);
CREATE INDEX IF NOT EXISTS idx_workouts_user ON workout_logs(user_id,started_at);
CREATE INDEX IF NOT EXISTS idx_weights_user ON weigh_ins(user_id,recorded_at);
